values ('bbbb0004-0000-4000-8000-000000000006', 'en', null, 'Anatomy & Physiology', 'A guided first tour of the human body — how its levels of organization work together and how the skeletal, muscular, nervous, and cardiovascular systems keep it alive. Structure adapted from OpenStax Anatomy and Physiology 2e (CC BY 4.0).', null, 'foundations', 6, true, 'science', '{}')
