insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-000000000006', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Anatomy is the study of body structure; physiology is the study of…","options":["body chemistry only","how body parts function","disease causes","cell division"],"answer":1,"explanation":"Anatomy = structure, physiology = function — see ''An Introduction to the Human Body''."},{"prompt":"The correct order of structural levels, smallest to largest, is…","options":["organ, tissue, cell, system","cell, tissue, organ, organ system","tissue, cell, system, organ","system, organ, cell, tissue"],"answer":1,"explanation":"Cells build tissues, tissues build organs, organs build systems — ''Levels of Organization''."},{"prompt":"Homeostasis refers to the body''s ability to…","options":["grow continuously","maintain a stable internal environment","resist all disease","store fat"],"answer":1,"explanation":"Homeostasis keeps internal conditions steady — see Chapter 1."},{"prompt":"The living cells that build and maintain bone are called…","options":["osteoblasts","chondrocytes","myocytes","neurons"],"answer":0,"explanation":"Osteoblasts build bone matrix — covered in ''Bone Tissue and the Skeletal System''."},{"prompt":"Skeletal muscle contracts when thin actin filaments slide over thick filaments made of…","options":["collagen","myosin","keratin","elastin"],"answer":1,"explanation":"The sliding-filament model pairs actin with myosin — ''Muscle Tissue''."},{"prompt":"The part of a neuron that carries a signal away from the cell body is the…","options":["dendrite","axon","synapse","soma"],"answer":1,"explanation":"Axons send; dendrites receive — see ''The Nervous System and Nervous Tissue''."},{"prompt":"The chamber of the heart that pumps oxygen-rich blood to the whole body is the…","options":["right atrium","right ventricle","left ventricle","left atrium"],"answer":2,"explanation":"The thick-walled left ventricle drives systemic circulation — ''The Heart''."},{"prompt":"Gas exchange between air and blood happens in the lungs'' tiny sacs called…","options":["bronchi","alveoli","villi","nephrons"],"answer":1,"explanation":"Alveoli are the site of gas exchange — ''The Respiratory System''."}]}'::jsonb, null, 10),
  (2, 'The body''s levels of organization and homeostasis', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the levels of structural organization and explain how homeostasis is maintained. Warm-up: from the diagnostic, which is larger — a tissue or an organ?"},{"heading":"The idea","text":"The body is built in nested levels: *chemicals* combine into *cells*, the smallest living units; similar cells form *tissues* (the four types are epithelial, connective, muscle, and nervous); tissues combine into *organs*; organs that work together form an *organ system*; and all systems form the *organism*. Across every level, the body defends *homeostasis* — a stable internal state for variables like temperature, blood glucose, and pH. Most homeostasis runs on *negative feedback*: a receptor detects a change, a control center compares it to a set point, and an effector reverses the change."},{"heading":"Worked example","text":"Body temperature drifts above 37 °C on a hot day. Skin and hypothalamic receptors detect the rise; the hypothalamus (control center) signals effectors; sweat glands release sweat and skin vessels widen to shed heat. Temperature falls back toward the set point — a textbook negative-feedback loop."},{"heading":"Your turn","text":"Classify each item''s level: (1) a single red blood cell, (2) the stomach, (3) cardiac muscle tissue, (4) the digestive system. Answers: (1) cell, (2) organ, (3) tissue, (4) organ system."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking homeostasis means ''no change'' — it actually means change is constantly corrected around a set point. Mistake: confusing negative feedback (reverses change) with positive feedback (amplifies it, as in blood clotting). Exit: (a) What are the four tissue types? (b) Which feedback type restores a set point? Answers: epithelial, connective, muscle, nervous; negative feedback."}]}'::jsonb, 'Structure determines function — say it every lesson.', 12),
  (3, 'The skeletal system', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe the functions of bone and how bone tissue is built and remodeled. Warm-up: which cells lay down new bone matrix?"},{"heading":"The idea","text":"The skeleton does far more than provide a frame: it supports the body, protects organs (the skull guards the brain, the ribs the heart and lungs), enables movement by anchoring muscles, stores *calcium* and phosphate, and produces blood cells in red *bone marrow*. Bone is living tissue. *Osteoblasts* deposit new matrix, *osteocytes* are mature cells maintaining it, and *osteoclasts* resorb bone. Their balance drives *remodeling*, so the skeleton renews throughout life. The 206 bones split into the *axial skeleton* (skull, vertebral column, rib cage) and the *appendicular skeleton* (limbs and the girdles that attach them)."},{"heading":"Worked example","text":"A distance runner''s tibia thickens over months of training. Mechanical stress signals osteoblasts to add matrix where load is highest, while osteoclasts trim less-stressed regions. The net result — bone laid down along lines of stress — illustrates Wolff''s law: bone adapts to the forces placed on it."},{"heading":"Your turn","text":"Answer each: (1) Which cell resorbs bone? (2) Skull — axial or appendicular? (3) Femur — axial or appendicular? (4) Name one mineral the skeleton stores. (5) Where are blood cells made? Answers: (1) osteoclast, (2) axial, (3) appendicular, (4) calcium (or phosphate), (5) red bone marrow."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking bone is inert and unchanging — it is constantly remodeled. Mistake: swapping osteoblasts and osteoclasts. Exit: (a) Which cell Builds bone? (b) Which skeleton division includes the rib cage? Answers: osteoblasts; the axial skeleton."}]}'::jsonb, 'Osteoblasts Build; osteoclasts Carve (resorb).', 13),
  (4, 'The muscular system', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Distinguish the three muscle types and explain how a muscle contracts. Warm-up: which muscle type moves your bones voluntarily?"},{"heading":"The idea","text":"There are three muscle tissues: *skeletal* (striated, voluntary, moves bones), *cardiac* (striated, involuntary, only in the heart), and *smooth* (non-striated, involuntary, in vessel and organ walls). Skeletal muscle contracts by the *sliding-filament model*: a motor neuron releases acetylcholine, calcium is released inside the fiber, and thin *actin* filaments are pulled over thick *myosin* filaments by myosin cross-bridges. The filaments themselves don''t shrink — they slide past each other, shortening the sarcomere and thus the whole muscle."},{"heading":"Worked example","text":"You lift a cup. A motor neuron fires; acetylcholine crosses the neuromuscular junction; calcium floods the biceps fibers and exposes binding sites on actin. Myosin heads grab, pull, release, and re-grab — the ratchet repeats, sarcomeres shorten, and the forearm flexes. Relaxation follows once calcium is pumped back into storage."},{"heading":"Your turn","text":"Classify or answer: (1) heart muscle — which type? (2) muscle in artery walls — which type? (3) thin filament protein? (4) thick filament protein? (5) ion that triggers contraction? Answers: (1) cardiac, (2) smooth, (3) actin, (4) myosin, (5) calcium."},{"heading":"Common mistakes & exit ticket","text":"Mistake: believing filaments contract by getting shorter — they slide, overlapping more. Mistake: calling cardiac muscle voluntary. Exit: (a) Which muscle type is striated and voluntary? (b) What neurotransmitter triggers skeletal contraction? Answers: skeletal; acetylcholine."}]}'::jsonb, 'Actin is thin, myosin is thick — filaments slide, they don''t shorten.', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"The correct sequence from smallest to largest is…","options":["tissue → cell → organ → system","cell → tissue → organ → organ system","organ → system → tissue → cell","cell → organ → tissue → system"],"answer":1,"explanation":"Cells form tissues, tissues form organs, organs form systems."},{"prompt":"Sweating to cool down after exercise is an example of…","options":["positive feedback","negative feedback","remodeling","a reflex arc only"],"answer":1,"explanation":"It reverses a rise in temperature toward the set point."},{"prompt":"The bone cell that resorbs (breaks down) matrix is the…","options":["osteoblast","osteocyte","osteoclast","chondrocyte"],"answer":2,"explanation":"Osteoclasts Carve bone away; osteoblasts Build it."},{"prompt":"The rib cage and vertebral column belong to the…","options":["appendicular skeleton","axial skeleton","muscular system","smooth muscle"],"answer":1,"explanation":"The axial skeleton runs along the body''s central axis."},{"prompt":"In the sliding-filament model, thin actin filaments are pulled over thick filaments made of…","options":["collagen","myosin","keratin","titin"],"answer":1,"explanation":"Myosin cross-bridges pull on actin."},{"prompt":"The involuntary striated muscle found only in the heart is…","options":["skeletal muscle","smooth muscle","cardiac muscle","connective tissue"],"answer":2,"explanation":"Cardiac muscle is striated but involuntary and unique to the heart."}]}'::jsonb, null, 8),
  (6, 'The nervous system', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe how neurons signal and how the nervous system is divided. Warm-up: which part of a neuron carries the signal away from the cell body?"},{"heading":"The idea","text":"The nervous system splits into the *central nervous system* (CNS — brain and spinal cord) and the *peripheral nervous system* (PNS — all other nerves). Its signaling cells are *neurons*: *dendrites* receive input, the *cell body* integrates it, and the *axon* carries the outgoing signal. A signal travels as an electrical *action potential* down the axon; at the *synapse* it becomes chemical, releasing *neurotransmitters* that cross the gap to the next cell. *Myelin*, made by glial cells, insulates axons so impulses jump quickly between gaps. The PNS itself divides into somatic (voluntary) and autonomic (involuntary) branches."},{"heading":"Worked example","text":"You touch a hot pan. Sensory neurons carry the signal to the spinal cord, which immediately fires motor neurons to withdraw the hand — a *reflex arc* that acts before the brain consciously registers pain. Only afterward does the message reach the cortex and you feel the burn."},{"heading":"Your turn","text":"Answer each: (1) Brain and spinal cord form which division? (2) Which neuron part receives signals? (3) What crosses the synapse? (4) What insulates axons for speed? (5) Voluntary movement uses the somatic or autonomic branch? Answers: (1) central nervous system, (2) dendrite, (3) neurotransmitters, (4) myelin, (5) somatic."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking neurons physically touch — they are separated by the synaptic gap. Mistake: assuming every response is routed through the brain — reflexes are handled by the spinal cord. Exit: (a) Axon: signal in or out? (b) What form does the signal take along the axon? Answers: out; an electrical action potential."}]}'::jsonb, 'Dendrite in, axon out — signals cross the synapse chemically.', 13),
  (7, 'The cardiovascular system', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Trace blood through the heart and name the two circuits. Warm-up: which chamber pumps blood to the entire body?"},{"heading":"The idea","text":"The heart has four chambers: two upper *atria* that receive blood and two lower *ventricles* that pump it. Blood moves in two circuits. In the *pulmonary circuit*, the right ventricle sends oxygen-poor blood to the lungs to pick up oxygen and release carbon dioxide. In the *systemic circuit*, the oxygen-rich blood returns to the left atrium, drops to the left ventricle, and is pumped to the whole body. *Arteries* carry blood away from the heart, *veins* return it, and *capillaries* — walls one cell thick — are where oxygen and nutrients actually exchange with tissues. Valves between chambers keep blood flowing one way."},{"heading":"Worked example","text":"Follow one red blood cell: it enters the right atrium (oxygen-poor), drops to the right ventricle, is pumped to the lungs where it loads oxygen, returns to the left atrium, drops to the left ventricle, and is driven out the aorta to the body. The left ventricle''s wall is thickest because it must generate the pressure for that long systemic journey."},{"heading":"Your turn","text":"Answer each: (1) Which chambers receive blood? (2) Which circuit goes to the lungs? (3) Do arteries carry blood toward or away from the heart? (4) Where does gas exchange with tissues occur? (5) Which ventricle has the thickest wall? Answers: (1) the atria, (2) pulmonary, (3) away, (4) capillaries, (5) the left ventricle."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming all arteries carry oxygen-rich blood — the pulmonary artery carries oxygen-poor blood to the lungs. Mistake: swapping atria (receive) and ventricles (pump). Exit: (a) Which vessels return blood to the heart? (b) Which circuit serves the whole body? Answers: veins; the systemic circuit."}]}'::jsonb, 'Arteries carry blood Away from the heart; veins return it.', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"homeostasis","translation":"the maintenance of a stable internal environment around a set point","example":"Shivering and sweating both defend homeostasis in body temperature."},{"term":"osteoblast","translation":"a cell that builds new bone matrix","example":"Osteoblasts add bone along lines of mechanical stress."},{"term":"sarcomere","translation":"the contractile unit of skeletal muscle, shortened when filaments slide","example":"As actin slides over myosin, each sarcomere shortens."},{"term":"synapse","translation":"the junction where a signal passes chemically from one neuron to the next","example":"Neurotransmitters carry the message across the synapse."},{"term":"alveolus","translation":"a tiny air sac in the lung where gases are exchanged with the blood","example":"Oxygen diffuses from each alveolus into surrounding capillaries."},{"term":"capillary","translation":"the smallest blood vessel, one cell thick, where exchange with tissues occurs","example":"Nutrients and oxygen leave the blood through capillary walls."}]}'::jsonb, null, 9),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"In a neuron, the outgoing signal travels along the…","options":["dendrite","axon","synapse","cell body"],"answer":1,"explanation":"The axon carries the action potential away from the cell body."},{"prompt":"Neurotransmitters are released to cross the…","options":["myelin sheath","synapse","capillary","sarcomere"],"answer":1,"explanation":"The synapse is the gap between neurons."},{"prompt":"The pulmonary circuit carries blood between the heart and the…","options":["brain","lungs","kidneys","liver"],"answer":1,"explanation":"The pulmonary circuit sends blood to the lungs for gas exchange."},{"prompt":"Blood vessels that carry blood away from the heart are…","options":["veins","arteries","capillaries","venules"],"answer":1,"explanation":"Arteries carry blood Away; veins return it."},{"prompt":"Gas exchange in the lungs takes place in the…","options":["bronchi","trachea","alveoli","pleura"],"answer":2,"explanation":"Alveoli are the thin-walled sacs where oxygen and CO2 are exchanged."},{"prompt":"The chamber that pumps oxygen-rich blood into the systemic circuit is the…","options":["right atrium","right ventricle","left ventricle","left atrium"],"answer":2,"explanation":"The thick-walled left ventricle drives systemic circulation."}]}'::jsonb, null, 8),
  (10, 'Applied project: map a homeostatic response', 'writing', '{"sections":[{"heading":"The task","text":"Choose one everyday challenge to the body — sprinting to catch a bus, stepping into cold water, or eating a sugary meal — and map how multiple organ systems cooperate to restore homeostasis. You are not running an experiment; you are tracing a physiological response step by step."},{"heading":"Milestones","text":"1) State the variable being disturbed and its rough set point (e.g. body temperature ~37 °C, or blood oxygen). 2) Identify the receptor, control center, and effector in the feedback loop. 3) Describe how at least two systems from the course (skeletal, muscular, nervous, cardiovascular, respiratory) contribute. 4) State whether the loop is negative or positive feedback and justify it."},{"heading":"Self-check rubric","text":"✔ The disturbed variable and set point are named. ✔ Receptor, control center, and effector are each identified. ✔ At least two organ systems are correctly connected to the response. ✔ You classified the feedback type and explained why. If all four hold, you''ve reasoned like a physiologist."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-000000000006' and l.position = v.pos
);
